import sys
from functools import lru_cache

d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
a = list(map(int, d[2:2 + n]))

@lru_cache(maxsize=None)
def f(l, r, left):
    if left == 0:
        return 0
    return max(a[l] + f(l + 1, r, left - 1), a[r] + f(l, r - 1, left - 1))

print(f(0, n - 1, k))

